(4183583, 599507, 83577, '<td valign="top">awesome shot .....i can''t wait to see this after the voting so i can see the specifics on equipment and hopefully set up</td>', 'awesome shot .....i can''t wait to see this after the voting so i can see the specifics on equipment and hopefully set up', '2007-10-20 19:23:42.000000', NULL, 1),
