(4183623, 600839, 83577, '<td valign="top">I love the shot...made me look it up to learn about it.I''ll probably never stay there for $2000 dollars a night but it is a fascinating building both inside and out.</td>', 'I love the shot...made me look it up to learn about it.I''ll probably never stay there for $2000 dollars a night but it is a fascinating building both inside and out.', '2007-10-20 19:32:20.000000', NULL, 1),
(4183650, 601085, 80542, '<td valign="top">Fun shot!</td>', 'Fun shot!', '2007-10-20 19:48:51.000000', NULL, 1),
(4183652, 600988, 80542, '<td valign="top">nice one!</td>', 'nice one!', '2007-10-20 19:49:27.000000', NULL, 1),
(4183656, 601001, 80542, '<td valign="top">Interesting angle and the colors are strong.</td>', 'Interesting angle and the colors are strong.', '2007-10-20 19:50:19.000000', NULL, 1),
(4183660, 600923, 80542, '<td valign="top">The cloud swirls are awesome.</td>', 'The cloud swirls are awesome.', '2007-10-20 19:53:07.000000', NULL, 1),
(4183663, 601153, 80542, '<td valign="top">So pretty.  The focus on the bird is great, the limbs so natural-looking and the background light and pattern adds so much to the overall feel.  Great photo!</td>', 'So pretty.  The focus on the bird is great, the limbs so natural-looking and the background light and pattern adds so much to the overall feel.  Great photo!', '2007-10-20 19:55:16.000000', NULL, 1),
(4183664, 601203, 80542, '<td valign="top">nice capture</td>', 'nice capture', '2007-10-20 19:55:32.000000', NULL, 1),
(4183667, 599849, 80542, '<td valign="top">Nice composition, lighting and overall feel of balance.</td>', 'Nice composition, lighting and overall feel of balance.', '2007-10-20 19:58:17.000000', NULL, 1),
(4183671, 601183, 80542, '<td valign="top">I like the rawness of the wet wood.  I''d like to see a tighter crop on the crates only, but cool shot.</td>', 'I like the rawness of the wet wood.  I''d like to see a tighter crop on the crates only, but cool shot.', '2007-10-20 20:01:31.000000', NULL, 1),
(4183673, 601105, 80542, '<td valign="top">nice balance - very peaceful</td>', 'nice balance - very peaceful', '2007-10-20 20:02:22.000000', NULL, 1),
(4183677, 598637, 80542, '<td valign="top">The clarity here is amazing... and beautiful.  Wonderful complimentary textures, too.</td>', 'The clarity here is amazing... and beautiful.  Wonderful complimentary textures, too.', '2007-10-20 20:04:36.000000', NULL, 1),
(4183681, 600906, 80542, '<td valign="top">awesome set-up here!</td>', 'awesome set-up here!', '2007-10-20 20:06:18.000000', NULL, 1),
