(4183689, 601064, 80542, '<td valign="top">Beautiful photograph!</td>', 'Beautiful photograph!', '2007-10-20 20:10:44.000000', NULL, 1),
(4183697, 599894, 80542, '<td valign="top">very interesting.  makes me think of a polaroid transfer.</td>', 'very interesting.  makes me think of a polaroid transfer.', '2007-10-20 20:15:34.000000', NULL, 1),
(4183703, 600946, 80542, '<td valign="top">Wow!  This is really out of this world looking.</td>', 'Wow!  This is really out of this world looking.', '2007-10-20 20:18:44.000000', NULL, 1),
(4183704, 601096, 80542, '<td valign="top">nice</td>', 'nice', '2007-10-20 20:18:58.000000', NULL, 1),
(4183709, 600471, 12733, '<td valign="top">A beautiful flower on a jumbled, confusing background</td>', 'A beautiful flower on a jumbled, confusing background', '2007-10-20 20:25:10.000000', NULL, 1),
(4183713, 600647, 12733, '<td valign="top">Nice view, but the haze really cuts out the detail.</td>', 'Nice view, but the haze really cuts out the detail.', '2007-10-20 20:26:11.000000', NULL, 1),
(4183716, 601010, 12733, '<td valign="top">Amazing point of view, it changes the whole vision.</td>', 'Amazing point of view, it changes the whole vision.', '2007-10-20 20:26:53.000000', NULL, 1),
(4183811, 601138, 83313, '<td valign="top">I''ll take your word that it''s night. Looks almost like broad daylight, except for that greenish glow near the exhausts.  That''s some great night photography!</td>', 'I''ll take your word that it''s night. Looks almost like broad daylight, except for that greenish glow near the exhausts.  That''s some great night photography!', '2007-10-20 21:48:37.000000', NULL, 1),
(4183816, 601174, 83313, '<td valign="top">A nice view. I like the use of b/w for this subject.</td>', 'A nice view. I like the use of b/w for this subject.', '2007-10-20 21:53:43.000000', NULL, 1),
(4183822, 598503, 23484, '<td valign="top"><b>V</b>ery cool shot.</td>', 'Very cool shot.', '2007-10-20 21:55:54.000000', NULL, 1),
(4183823, 601074, 83313, '<td valign="top">Interesting title. It makes sense, though. I like the glow, but the rest of the image seems a little too dark. The edges of the box it is in are a little distracting from the subject as well.</td>', 'Interesting title. It makes sense, though. I like the glow, but the rest of the image seems a little too dark. The edges of the box it is in are a little distracting from the subject as well.', '2007-10-20 21:56:15.000000', NULL, 1),
(4183829, 600724, 83313, '<td valign="top">This is very nice, though I think there is a little too much empty water toward the bottom of the frame. I think cropping might give it some more impact.</td>', 'This is very nice, though I think there is a little too much empty water toward the bottom of the frame. I think cropping might give it some more impact.', '2007-10-20 21:58:16.000000', NULL, 1),
(4183831, 600566, 83313, '<td valign="top">Good, but not doing too much for me. the eye is drawn up to the bright wall.</td>', 'Good, but not doing too much for me. the eye is drawn up to the bright wall.', '2007-10-20 21:59:24.000000', NULL, 1),
(4183835, 601033, 83313, '<td valign="top">A good close up. Nice, bright orange.</td>', 'A good close up. Nice, bright orange.', '2007-10-20 22:00:21.000000', NULL, 1),
(4183838, 599851, 83313, '<td valign="top">a good still life, but my eye is torn between which pot is the subject of this photo.</td>', 'a good still life, but my eye is torn between which pot is the subject of this photo.', '2007-10-20 22:01:22.000000', NULL, 1),
(4183843, 601000, 83313, '<td valign="top">Wow.... Just a great image. deep, but still subtle colors and a great backlighting. Another one for my faves list.</td>', 'Wow.... Just a great image. deep, but still subtle colors and a great backlighting. Another one for my faves list.', '2007-10-20 22:02:52.000000', NULL, 1),
(4183844, 601146, 83313, '<td valign="top">Great composition and colors, but I find my eye being drawn to the out of focus barn.</td>', 'Great composition and colors, but I find my eye being drawn to the out of focus barn.', '2007-10-20 22:03:39.000000', NULL, 1),
(4183848, 600958, 83313, '<td valign="top">Interesting, and needs some explanation. is this a street person on laundry day? I''ll check back on this one when the challenge is over.</td>', 'Interesting, and needs some explanation. is this a street person on laundry day? I''ll check back on this one when the challenge is over.', '2007-10-20 22:05:27.000000', NULL, 1),
(4183852, 600732, 83313, '<td valign="top">Great use of contrast, color &amp; texture. Another for my faves list.</td>', 'Great use of contrast, color & texture. Another for my faves list.', '2007-10-20 22:07:00.000000', NULL, 1),
(4183854, 599934, 83313, '<td valign="top">A nice portrait of this boy. Good choice of b/w.</td>', 'A nice portrait of this boy. Good choice of b/w.', '2007-10-20 22:07:40.000000', NULL, 1),
(4183871, 598843, 83313, '<td valign="top">Probably the same way you got there. Nice shadows and overall look.</td>', 'Probably the same way you got there. Nice shadows and overall look.', '2007-10-20 22:12:25.000000', NULL, 1),
(4183873, 601048, 83313, '<td valign="top">a "Wow" picture. Nice shooting.</td>', 'a "Wow" picture. Nice shooting.', '2007-10-20 22:13:07.000000', NULL, 1),
