(4185212, 600487, 78196, '<td valign="top">Taken a little bit too far off the ground to really make us feel like a bug. Lacking in sharpness and many will not like the flare very much.</td>', 'Taken a little bit too far off the ground to really make us feel like a bug. Lacking in sharpness and many will not like the flare very much.', '2007-10-21 16:15:04.000000', NULL, 1),
(4185215, 601070, 78196, '<td valign="top">A good idea that could potentially be improved if the centre of the flower were more in focus and if you could lose the reflections on the right side of the magnifying glass.</td>', 'A good idea that could potentially be improved if the centre of the flower were more in focus and if you could lose the reflections on the right side of the magnifying glass.', '2007-10-21 16:15:59.000000', NULL, 1),
(4185216, 600102, 78196, '<td valign="top">Well composed but white balance too cool and lacking in real interest.</td>', 'Well composed but white balance too cool and lacking in real interest.', '2007-10-21 16:16:43.000000', NULL, 1),
(4185220, 600142, 78196, '<td valign="top">The white balance seems a little too cool on this image, and though the angle is quite effective on this reasonably interesting bit of architecture, there''s not enough to sustain our interest.</td>', 'The white balance seems a little too cool on this image, and though the angle is quite effective on this reasonably interesting bit of architecture, there''s not enough to sustain our interest.', '2007-10-21 16:17:45.000000', NULL, 1),
(4185223, 601203, 78196, '<td valign="top">Super colours and very well executed.</td>', 'Super colours and very well executed.', '2007-10-21 16:18:10.000000', NULL, 1),
(4185225, 600545, 78196, '<td valign="top">POV is quite good here, however the lack of contrast prevents this being a really effective B&amp;W.</td>', 'POV is quite good here, however the lack of contrast prevents this being a really effective B&W.', '2007-10-21 16:18:40.000000', NULL, 1),
(4185227, 601055, 78196, '<td valign="top">Daring use of inversion, however excitement is limited by the dullness of the colours. Many will find the inversion disorientating, however this may not have met the challenge if it were the right way up ;)</td>', 'Daring use of inversion, however excitement is limited by the dullness of the colours. Many will find the inversion disorientating, however this may not have met the challenge if it were the right way up ;)', '2007-10-21 16:19:32.000000', NULL, 1),
(4185231, 601057, 78196, '<td valign="top">Bold, distinctive, brave. Leaves me a little cold (perhaps the crop on the left hand is too tight - our eyes should be led there but aren''t). Deliciously noisy and conversion is excellent.</td>', 'Bold, distinctive, brave. Leaves me a little cold (perhaps the crop on the left hand is too tight - our eyes should be led there but aren''t). Deliciously noisy and conversion is excellent.', '2007-10-21 16:20:56.000000', NULL, 1),
(4185232, 600366, 78196, '<td valign="top">Great choice of subject, nice and sharp - this one will do well.</td>', 'Great choice of subject, nice and sharp - this one will do well.', '2007-10-21 16:21:18.000000', NULL, 1),
(4185234, 601052, 78196, '<td valign="top">Lacks interest. Only touches the surface of the challenge description. Our attention should be drawn to something different and interesting as a result of the changed perspective.</td>', 'Lacks interest. Only touches the surface of the challenge description. Our attention should be drawn to something different and interesting as a result of the changed perspective.', '2007-10-21 16:22:21.000000', NULL, 1),
(4185236, 601014, 78196, '<td valign="top">Nice composition and a beautiful home. A push for the challenge description.</td>', 'Nice composition and a beautiful home. A push for the challenge description.', '2007-10-21 16:22:55.000000', NULL, 1),
