(4185238, 600940, 10818, '<td valign="top">Wow, thats amazing.  If not for that little drop I never would have thought that was a reflection.  Super photo.</td>', 'Wow, thats amazing.  If not for that little drop I never would have thought that was a reflection.  Super photo.', '2007-10-21 16:23:21.000000', NULL, 1),
(4185241, 598503, 78196, '<td valign="top">Super conversion. Not sure about the pose of the model at the end, but I like everything else about it.</td>', 'Super conversion. Not sure about the pose of the model at the end, but I like everything else about it.', '2007-10-21 16:23:47.000000', NULL, 1),
(4185244, 601227, 78196, '<td valign="top">A nice take on the challenge. Brave and ugly. It''s not going to do well but I admire your originality.</td>', 'A nice take on the challenge. Brave and ugly. It''s not going to do well but I admire your originality.', '2007-10-21 16:24:33.000000', NULL, 1),
(4185246, 599343, 78196, '<td valign="top">Pretty enough but there''s no new perspective created here.</td>', 'Pretty enough but there''s no new perspective created here.', '2007-10-21 16:24:53.000000', NULL, 1),
(4185248, 600745, 78196, '<td valign="top">My overall impression of this shot is of an opportunity lost. It doesn''t help that the man is in the shade but I feel something much more darking could have been done with the composition - the scenery alone doesn''t add to the mood you''ve so nearly created. If we could see more of the man I feel it would help.</td>', 'My overall impression of this shot is of an opportunity lost. It doesn''t help that the man is in the shade but I feel something much more darking could have been done with the composition - the scenery alone doesn''t add to the mood you''ve so nearly created. If we could see more of the man I feel it would help.', '2007-10-21 16:26:01.000000', NULL, 1),
(4185250, 599516, 10818, '<td valign="top">Great shot.  Quite interesting, has that MC Escher effect.</td>', 'Great shot.  Quite interesting, has that MC Escher effect.', '2007-10-21 16:26:18.000000', NULL, 1),
(4185251, 601059, 78196, '<td valign="top">There''s some pretty nasty vignetting going on in the bottom corners especially, and the focus is generally off. This either needs a very shallow or very deep depth of field - when it''s something in the middle as this one is, the effect is lost.</td>', 'There''s some pretty nasty vignetting going on in the bottom corners especially, and the focus is generally off. This either needs a very shallow or very deep depth of field - when it''s something in the middle as this one is, the effect is lost.', '2007-10-21 16:27:13.000000', NULL, 1),
(4185253, 601035, 78196, '<td valign="top">There''s a reasonable amount of intrigue here, I''m left wondering what they''re looking at. I wonder if you could have been more daring with the negative space you''ve created. There''s also something about the colour of the grass which doesn''t seem lifelike to me, perhaps this is a contender for an effective black and white conversion?</td>', 'There''s a reasonable amount of intrigue here, I''m left wondering what they''re looking at. I wonder if you could have been more daring with the negative space you''ve created. There''s also something about the colour of the grass which doesn''t seem lifelike to me, perhaps this is a contender for an effective black and white conversion?', '2007-10-21 16:28:39.000000', NULL, 1),
(4185254, 601055, 10818, '<td valign="top">Wow!  Thats so cool, awesome shot and fantastic POV.</td>', 'Wow!  Thats so cool, awesome shot and fantastic POV.', '2007-10-21 16:29:03.000000', NULL, 1),
(4185255, 601235, 78196, '<td valign="top">Focus is off in the centre of the image which lets this down somewhat.</td>', 'Focus is off in the centre of the image which lets this down somewhat.', '2007-10-21 16:29:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4185258, 598750, 10818, '<td valign="top">What majestic bird, beautiful photo.</td>', 'What majestic bird, beautiful photo.', '2007-10-21 16:30:04.000000', NULL, 1),
(4185259, 600728, 78196, '<td valign="top">Lighting and motion blur are well done (I think, the motion blur seems a little artificial to me but I''m sure it''s not) but I think the house appearing towards the bottom is a distraction.</td>', 'Lighting and motion blur are well done (I think, the motion blur seems a little artificial to me but I''m sure it''s not) but I think the house appearing towards the bottom is a distraction.', '2007-10-21 16:30:08.000000', NULL, 1),
(4185261, 601191, 78196, '<td valign="top">Unique take on the challenge that would have benefitted from a more interesting subject!</td>', 'Unique take on the challenge that would have benefitted from a more interesting subject!', '2007-10-21 16:30:41.000000', NULL, 1),
(4185263, 600998, 78196, '<td valign="top">Nice, bright, saturated colours and you just about get away with the daring DoF you''ve opted for. Rather pretty.</td>', 'Nice, bright, saturated colours and you just about get away with the daring DoF you''ve opted for. Rather pretty.', '2007-10-21 16:31:35.000000', NULL, 1),
(4185264, 600366, 10818, '<td valign="top">Funny photo, well done.  Quite crisp and colorful.</td>', 'Funny photo, well done.  Quite crisp and colorful.', '2007-10-21 16:31:40.000000', NULL, 1),
(4185267, 599308, 78196, '<td valign="top">Sadly there are both blown highlights and burnt-out shadows here, and the focus is off. I suspect a camera of low quality.</td>', 'Sadly there are both blown highlights and burnt-out shadows here, and the focus is off. I suspect a camera of low quality.', '2007-10-21 16:32:43.000000', NULL, 1),
(4185268, 601147, 10818, '<td valign="top">I try not to pee at the dinner table.  :)</td>', 'I try not to pee at the dinner table.  :)', '2007-10-21 16:33:30.000000', NULL, 1),
(4185269, 601117, 78196, '<td valign="top">Excellent. Colours nice and saturated. Motion blur also good. It takes us a moment to see the man but it works well. Deep purple fringing towards the horizon is less good, but not your fault!</td>', 'Excellent. Colours nice and saturated. Motion blur also good. It takes us a moment to see the man but it works well. Deep purple fringing towards the horizon is less good, but not your fault!', '2007-10-21 16:33:38.000000', NULL, 1),
(4185273, 600913, 10818, '<td valign="top">Thats stunning.  What a rush that must be, both for the photographer and the parachuter.</td>', 'Thats stunning.  What a rush that must be, both for the photographer and the parachuter.', '2007-10-21 16:36:24.000000', NULL, 1),
(4185275, 601151, 10818, '<td valign="top">Ahhh, just adorable.  The green pasture is great contrast with the animal.</td>', 'Ahhh, just adorable.  The green pasture is great contrast with the animal.', '2007-10-21 16:38:58.000000', NULL, 1),
(4185285, 600840, 10818, '<td valign="top">HA ! That is great.  Funny shot, interesting POV.</td>', 'HA ! That is great.  Funny shot, interesting POV.', '2007-10-21 16:42:20.000000', NULL, 1),
(4185299, 599183, 10818, '<td valign="top">Now that is peculiar.  Quite the strange looking cow, nice shot.</td>', 'Now that is peculiar.  Quite the strange looking cow, nice shot.', '2007-10-21 16:45:19.000000', NULL, 1),
(4185302, 600386, 10818, '<td valign="top">Creepy and eerie, great tones.</td>', 'Creepy and eerie, great tones.', '2007-10-21 16:45:53.000000', NULL, 1),
(4185304, 600966, 10818, '<td valign="top">What beautiful eyes, great looking pooch.</td>', 'What beautiful eyes, great looking pooch.', '2007-10-21 16:47:58.000000', NULL, 1),
(4185311, 601047, 10818, '<td valign="top">That is wild !  Love it, I really cant tell whats going on...but it is really cool.</td>', 'That is wild !  Love it, I really cant tell whats going on...but it is really cool.', '2007-10-21 16:52:08.000000', NULL, 1),
(4185317, 601071, 10818, '<td valign="top">I love old bridges, and this shot really works.  Great one.</td>', 'I love old bridges, and this shot really works.  Great one.', '2007-10-21 16:53:44.000000', NULL, 1),
(4185322, 600597, 10818, '<td valign="top">Looks like lovely pastures, nice lines.  Looks a bit blown out however.</td>', 'Looks like lovely pastures, nice lines.  Looks a bit blown out however.', '2007-10-21 16:58:34.000000', NULL, 1),
(4185323, 601048, 10818, '<td valign="top">Amazing how much detail you achieved in the photo considering the sun.  Fabulous shot.</td>', 'Amazing how much detail you achieved in the photo considering the sun.  Fabulous shot.', '2007-10-21 17:00:20.000000', NULL, 1),
(4185326, 598503, 10818, '<td valign="top">That is awesome.  Love the gritty feel, highest marks.</td>', 'That is awesome.  Love the gritty feel, highest marks.', '2007-10-21 17:02:36.000000', NULL, 1),
(4185334, 600839, 10818, '<td valign="top">What a fabulous building, great colors.  I may have rotated just a tad to the left.</td>', 'What a fabulous building, great colors.  I may have rotated just a tad to the left.', '2007-10-21 17:09:50.000000', NULL, 1),
(4185367, 600728, 83313, '<td valign="top">Nice enhancement of the colors, and use of shadows. It leaves me wondering what the story is.</td>', 'Nice enhancement of the colors, and use of shadows. It leaves me wondering what the story is.', '2007-10-21 17:39:52.000000', NULL, 1),
(4185371, 599233, 10818, '<td valign="top">Great looking old ax, super background.</td>', 'Great looking old ax, super background.', '2007-10-21 17:41:25.000000', NULL, 1),
(4185381, 601127, 10818, '<td valign="top">It probably wont score real well, but I find it strangely compelling. 7</td>', 'It probably wont score real well, but I find it strangely compelling. 7', '2007-10-21 17:44:20.000000', NULL, 1),
(4185393, 600811, 10818, '<td valign="top">Looks like a still life photo, quite amazing. Well done.</td>', 'Looks like a still life photo, quite amazing. Well done.', '2007-10-21 17:49:12.000000', NULL, 1),
(4185398, 600041, 10818, '<td valign="top">I don''t see that many ladies climbing ladders where I live. I think I should move.  :)</td>', 'I don''t see that many ladies climbing ladders where I live. I think I should move.  :)', '2007-10-21 17:52:03.000000', NULL, 1),
(4185401, 600732, 10818, '<td valign="top">That is beautiful, great contrast and lighting.</td>', 'That is beautiful, great contrast and lighting.', '2007-10-21 17:53:41.000000', NULL, 1),
(4185403, 600863, 10818, '<td valign="top">Thats pretty, great job using the park bench...looks great.</td>', 'Thats pretty, great job using the park bench...looks great.', '2007-10-21 17:55:13.000000', NULL, 1),
(4185415, 600557, 18367, '<td valign="top">First image I have looked at in this challenge and I must say I do really like this novel approach and the options you give to the viewer. My only criticism rests in the fact that I find the encroachment of the sunlight in the lower left hand side a distraction.  Nicely done, and good luck with the challenge.</td>', 'First image I have looked at in this challenge and I must say I do really like this novel approach and the options you give to the viewer. My only criticism rests in the fact that I find the encroachment of the sunlight in the lower left hand side a distraction.  Nicely done, and good luck with the challenge.', '2007-10-21 18:04:59.000000', NULL, 1),
(4185420, 600811, 18367, '<td valign="top">I am quite intrigued as to why the landing gear is deployed with the aircraft in this position.  A very nice image, but I find the pink hue at the edge of the clouds to be a distraction.  Very nice stop action on this one. Good luck<br/>.</td>', 'I am quite intrigued as to why the landing gear is deployed with the aircraft in this position.  A very nice image, but I find the pink hue at the edge of the clouds to be a distraction.  Very nice stop action on this one. Good luck.', '2007-10-21 18:08:55.000000', NULL, 1),
(4185472, 600102, 18367, '<td valign="top">The focus in the image seems a tad soft, but the major problem lies in the fact  that you took this image in the blazing sunlight.  The presence of the sunspot does little to enhance this image, nor does the presence of the tree between the horse''s legs.  Good luck.</td>', 'The focus in the image seems a tad soft, but the major problem lies in the fact  that you took this image in the blazing sunlight.  The presence of the sunspot does little to enhance this image, nor does the presence of the tree between the horse''s legs.  Good luck.', '2007-10-21 18:38:23.000000', NULL, 1),
(4185477, 600647, 78527, '<td valign="top">ok, but a bit sprawling and without a focal point</td>', 'ok, but a bit sprawling and without a focal point', '2007-10-21 18:45:52.000000', NULL, 1),
(4185478, 600988, 78527, '<td valign="top">unusual</td>', 'unusual', '2007-10-21 18:46:37.000000', NULL, 1),
(4185527, 601141, 18367, '<td valign="top">A beautiful image that offers a refreshing take on the challenge topic.  The vibrant colours against the somber background, coupled with the DOF and focus all combine to make this a very attractive image.  Well done.</td>', 'A beautiful image that offers a refreshing take on the challenge topic.  The vibrant colours against the somber background, coupled with the DOF and focus all combine to make this a very attractive image.  Well done.', '2007-10-21 19:25:12.000000', NULL, 1),
(4185533, 599894, 45475, '<td valign="top">Well this is the most intriguing piece of work I''ve seen in a long time. Beats me how you managed that dof without creative pp, but quite happy to give the benefit of the doubt here. 10 and favourite for sure :)</td>', 'Well this is the most intriguing piece of work I''ve seen in a long time. Beats me how you managed that dof without creative pp, but quite happy to give the benefit of the doubt here. 10 and favourite for sure :)', '2007-10-21 19:28:54.000000', NULL, 1),
(4185566, 600863, 74588, '<td valign="top">what a colours   9</td>', 'what a colours   9', '2007-10-21 19:55:17.000000', NULL, 1),
(4185569, 601246, 74588, '<td valign="top">on a lazy afternoon   7</td>', 'on a lazy afternoon   7', '2007-10-21 19:58:49.000000', NULL, 1),
(4185595, 600913, 83313, '<td valign="top">A wonderful feeling of flying. Looks like fun!</td>', 'A wonderful feeling of flying. Looks like fun!', '2007-10-21 20:18:07.000000', NULL, 1),
(4185600, 601126, 83313, '<td valign="top">Yes, he does look a little irritated. Nice shot.</td>', 'Yes, he does look a little irritated. Nice shot.', '2007-10-21 20:19:36.000000', NULL, 1),
(4185601, 599878, 83313, '<td valign="top">I''m afraid this one went over my head...</td>', 'I''m afraid this one went over my head...', '2007-10-21 20:20:08.000000', NULL, 1),
(4185661, 601071, 78021, '<td valign="top">Nice use of B&amp;W</td>', 'Nice use of B&W', '2007-10-21 21:12:55.000000', NULL, 1),
(4185664, 598637, 78021, '<td valign="top">would have liked more if more of the far shore was visible.  The stillness of the lake is amaizing!</td>', 'would have liked more if more of the far shore was visible.  The stillness of the lake is amaizing!', '2007-10-21 21:14:04.000000', NULL, 1),
(4185666, 600513, 78021, '<td valign="top">Internesting shot...the title does not match it though.</td>', 'Internesting shot...the title does not match it though.', '2007-10-21 21:14:59.000000', NULL, 1),
(4185672, 600895, 44304, '<td valign="top">I think that the border you''ve added helps to draw the eye into the subject, but it seems to be a bit overdone here.  I know it''s not legal in basic, but some burning around the edges would have looked a lot better.  Aside from that, you may get some comments on the noise, but I think it adds to the image.  Focus is dead on, so I''m guessing that you know your photography skills are adept enough to have done the noise on purpose.</td>', 'I think that the border you''ve added helps to draw the eye into the subject, but it seems to be a bit overdone here.  I know it''s not legal in basic, but some burning around the edges would have looked a lot better.  Aside from that, you may get some comments on the noise, but I think it adds to the image.  Focus is dead on, so I''m guessing that you know your photography skills are adept enough to have done the noise on purpose.', '2007-10-21 21:16:43.000000', NULL, 1),
(4185675, 600909, 78021, '<td valign="top">Interesting idea.  Execution could be better.  White ballance is way off.</td>', 'Interesting idea.  Execution could be better.  White ballance is way off.', '2007-10-21 21:17:20.000000', NULL, 1),
(4185790, 601127, 75386, '<td valign="top">Great percpective, I really like the long shadows along with the texture of the street</td>', 'Great percpective, I really like the long shadows along with the texture of the street', '2007-10-21 21:55:59.000000', NULL, 1),
(4185794, 600997, 75386, '<td valign="top">dnmc...but nice sunset</td>', 'dnmc...but nice sunset', '2007-10-21 21:57:49.000000', NULL, 1),
(4185862, 600207, 75386, '<td valign="top">Going back and forth on this one. Its is a not so usual pov.  But if the lines caused by the shadows were thicker we could maybe see what the picture is easier. Or does the fact that its hard to see the image is what makes it interesting.</td>', 'Going back and forth on this one. Its is a not so usual pov.  But if the lines caused by the shadows were thicker we could maybe see what the picture is easier. Or does the fact that its hard to see the image is what makes it interesting.', '2007-10-21 22:22:01.000000', NULL, 1),
