(4194664, 598503, 66597, '<td valign="top">Wow - what a cool photo! Congrats on your ribbon!</td>', 'Wow - what a cool photo! Congrats on your ribbon!', '2007-10-25 09:23:01.000000', NULL, 0),
(4194688, 600512, 61961, '<td valign="top">Terrific photo, great expression.  Welcome to DPChallenge!</td>', 'Terrific photo, great expression.  Welcome to DPChallenge!', '2007-10-25 09:40:53.000000', NULL, 0),
(4194740, 600366, 43410, '<td valign="top">as always, GREAT JOB Sandy :)  Keep up the great work :D</td>', 'as always, GREAT JOB Sandy :)  Keep up the great work :D', '2007-10-25 10:07:19.000000', NULL, 0),
(4194801, 600869, 34462, '<td valign="top">So that''s what they look like close up. I found one in my bed one night. However, I made her sleep outside. Great POV roz.</td>', 'So that''s what they look like close up. I found one in my bed one night. However, I made her sleep outside. Great POV roz.', '2007-10-25 10:30:22.000000', NULL, 0),
(4194935, 600733, 80473, '<td valign="top">I think I get it. It looks like "Point of View" may have been taken in several literal ways. Grainy, framed, disturbed...etc.</td>', 'I think I get it. It looks like "Point of View" may have been taken in several literal ways. Grainy, framed, disturbed...etc.', '2007-10-25 11:29:31.000000', NULL, 0),
(4195093, 600366, 43714, '<td valign="top">What a sweet shot, I love these adorable animals. You are the animal rocker!!!!!</td>', 'What a sweet shot, I love these adorable animals. You are the animal rocker!!!!!', '2007-10-25 13:15:23.000000', NULL, 0),
(4195470, 601179, 73601, '<td valign="top">You are such a unique photographer, always quality work. Grats on another great image and finish.</td>', 'You are such a unique photographer, always quality work. Grats on another great image and finish.', '2007-10-25 16:35:17.000000', NULL, 0),
(4195477, 600366, 34938, '<td valign="top">Congratulations Sandy. I saw this in Newport Beach LA in my hotel room, but my internet access stopped before I could comment. I am now home and it is 5:30am (jetlag -cannot sleep) so I thought I would stop to say well done. Great score</td>', 'Congratulations Sandy. I saw this in Newport Beach LA in my hotel room, but my internet access stopped before I could comment. I am now home and it is 5:30am (jetlag -cannot sleep) so I thought I would stop to say well done. Great score', '2007-10-25 16:39:01.000000', NULL, 0),
(4195480, 601203, 34938, '<td valign="top">another ribbon and a pb Jeff...well done. I love the oof background and the way the leaf just sits there</td>', 'another ribbon and a pb Jeff...well done. I love the oof background and the way the leaf just sits there', '2007-10-25 16:40:13.000000', NULL, 0),
(4195601, 600366, 11769, '<td valign="top">This is a beauty of an image. Wonderful point of view. Congrats on the blue!</td>', 'This is a beauty of an image. Wonderful point of view. Congrats on the blue!', '2007-10-25 17:29:36.000000', NULL, 0),
