(4196104, 600366, 69008, '<td valign="top">This has to be one of the best critter shots ever! I love those tall long tounged ones. I think you made the right choice too.  The angle and the expression are just precious, and the light, crop, and background are perfect.  Congrats on another blue.</td>', 'This has to be one of the best critter shots ever! I love those tall long tounged ones. I think you made the right choice too.  The angle and the expression are just precious, and the light, crop, and background are perfect.  Congrats on another blue.', '2007-10-25 22:53:41.000000', NULL, 0),
(4196113, 601203, 69008, '<td valign="top">Congrats on a good find, fine technique, and an attention arresting image as well as a ribbon.</td>', 'Congrats on a good find, fine technique, and an attention arresting image as well as a ribbon.', '2007-10-25 22:57:22.000000', NULL, 0),
