(4196969, 600520, 56002, '<td valign="top">I didn''t vote.  But I think this is a fine photo.  Full of interest and well executed.</td>', 'I didn''t vote.  But I think this is a fine photo.  Full of interest and well executed.', '2007-10-26 09:03:02.000000', NULL, 0),
(4197040, 601047, 30861, '<td valign="top">This is FANTASTIC! I''m glad I saw this one. Absolutely first-rate. I can only say "ditto" to what yanko said, and add that the luminosity of the image is startling. Well done!<br/> <br/>R.</td>', 'This is FANTASTIC! I''m glad I saw this one. Absolutely first-rate. I can only say "ditto" to what yanko said, and add that the luminosity of the image is startling. Well done! R.', '2007-10-26 10:10:47.000000', NULL, 0),
(4197118, 601203, 32997, '<td valign="top">very cool image...colours are perfect...</td>', 'very cool image...colours are perfect...', '2007-10-26 10:48:21.000000', NULL, 0),
